embeddedAssets.set("/src/app.js", "import { icons, logo, heroArt, serviceVisual } from './visuals.js';\nimport { services, stages, agents, projects } from './data.js';\nimport { initMotion } from './motion.js?v=hero-flow-2';\nimport { experienceSection, bindExperience } from './experience.js';\nimport { referenceHero, unlockSection, journalSection, renderStudio, bindStudio } from './studio.js?v=hero-flow-2';\n\nconst app = document.querySelector('#app');\nlet cleanupMotion = () => {};\nlet pageAbort;\nconst arrow = icons.arrow;\nconst diagonal = icons.diagonal;\nconst button = (label, href = '/contact', kind = 'primary') => `<a class=\"button button-${kind}\" href=\"${href}\"><span>${label}</span>${arrow}</a>`;\nconst eyebrow = (text, extra = '') => `<div class=\"eyebrow\"><span class=\"eyebrow-line\"></span>${text}${extra}</div>`;\nconst sectionTop = (number, name, right = '') => `<div class=\"section-top\"><span><i>${number}</i> ${name}</span><span>${right}</span></div>`;\n\nfunction header(path) {\n  const current = href => path === href || (href !== '/contact' && path.startsWith(href + '/'));\n  const links = [['/work','Selected work'],['/solutions','Solutions'],['/engagements','Engagements'],['/insights','Insights'],['/about','About us']];\n  const navLink = ([href,label], mobile=false) => `<a class=\"${mobile?'':'nav-link '}${current(href)?'active':''}\" href=\"${href}\" ${current(href)?'aria-current=\"page\"':''}>${label}${mobile?' '+diagonal:''}</a>`;\n  return `<header class=\"site-header\"><div class=\"reading-progress\" aria-hidden=\"true\"><i></i></div><div class=\"nav-container\"><a class=\"brand\" href=\"/\" aria-label=\"Aventrixx home\">${logo}<span>AVENTRIXX<span class=\"brand-period\">.</span></span></a><nav class=\"desktop-nav\" aria-label=\"Main navigation\"><div class=\"nav-dropdown\"><button class=\"nav-link dropdown-toggle ${path.startsWith('/services') ? 'active' : ''}\" aria-expanded=\"false\" aria-controls=\"capability-menu\">Capabilities <span class=\"chevron\">⌄</span></button><div id=\"capability-menu\" class=\"dropdown-menu\" hidden><span class=\"menu-label\">AN INTELLIGENT GROWTH SYSTEM</span>${services.map(s => `<a href=\"/services/${s.slug}\">${icons[s.icon]}<span>${s.name}<small>${s.short}</small></span>${diagonal}</a>`).join('')}<a class=\"menu-all\" href=\"/services\">Explore all capabilities ${arrow}</a></div></div>${links.map(link=>navLink(link)).join('')}</nav><a class=\"nav-contact\" href=\"/contact\">Let’s talk ${diagonal}</a><button class=\"mobile-toggle\" aria-label=\"Open navigation\" aria-expanded=\"false\" aria-controls=\"mobile-menu\"><span></span><span></span></button></div><nav id=\"mobile-menu\" class=\"mobile-menu\" aria-label=\"Mobile navigation\" hidden>${[['/services','Capabilities'],...links,['/contact','Let’s talk']].map(link=>navLink(link,true)).join('')}<span>DIGITAL EXPERIENCES. INTELLIGENT GROWTH.</span></nav></header>`;\n}\n\nfunction footer() {\n  return `<footer class=\"site-footer\"><div class=\"container\"><div class=\"footer-main\"><div class=\"footer-brand\"><a class=\"brand\" href=\"/\">${logo}<span>AVENTRIXX<span class=\"brand-period\">.</span></span></a><p>Beyond presence.<br>Into possibility.</p><span class=\"footer-descriptor\">A CREATIVE TECHNOLOGY & GROWTH STUDIO</span></div><div class=\"footer-column\"><h2>CAPABILITIES</h2>${services.map(s => `<a href=\"/services/${s.slug}\">${s.name}</a>`).join('')}</div><div class=\"footer-column\"><h2>EXPLORE</h2><a href=\"/work\">Selected work</a><a href=\"/#approach\">Our approach</a><a href=\"/solutions\">Business solutions</a><a href=\"/engagements\">Engagements</a><a href=\"/insights\">Studio insights</a><a href=\"/about\">About Aventrixx</a><a href=\"/contact\">Get in touch</a></div><div class=\"footer-connect\"><h2>YOUR NEXT CHAPTER</h2><p>Have something<br>ambitious in mind?</p><a href=\"/contact\">Let’s make it happen ${diagonal}</a><span><span class=\"status-dot\"></span> Open to new conversations</span></div></div><div class=\"footer-bottom\"><span>© ${new Date().getFullYear()} Aventrixx. All rights reserved.</span><span><a href=\"/privacy\">Privacy policy</a><a href=\"/terms\">Terms of use</a><button class=\"back-top\">Back to top ↑</button></span></div></div></footer>`;\n}\n\nfunction cta() {\n  return `<section class=\"cta-section container reveal\"><div class=\"cta-glow\"></div>${eyebrow('THE NEXT CHAPTER IS YOURS')}<h2>Let’s build what<br>comes <span class=\"text-gradient\">next.</span></h2><div class=\"cta-bottom\"><p>A clearer direction. A stronger presence.<br>A more intelligent way to grow.</p>${button('Build My Growth Strategy')}</div><span class=\"cta-coordinate\">AV / NEXT</span></section>`;\n}\n\nfunction capabilityCards() {\n  return services.map((s,i) => `<a class=\"service-card reveal\" href=\"/services/${s.slug}\" style=\"--reveal-delay:${i%3*70}ms\"><div class=\"service-card-top\"><span class=\"service-icon\">${icons[s.icon]}</span><span class=\"card-number\">0${i+1}</span></div><h3>${s.name}</h3><p>${s.short}</p><div class=\"card-bottom\"><span>Explore capability</span>${diagonal}</div></a>`).join('');\n}\n\nfunction showcase() {\n  return `<section id=\"capabilities\" class=\"showcase-section\"><div class=\"showcase-sticky\"><div class=\"container\">${sectionTop('01','CONNECTED CAPABILITIES','SIX CAPABILITIES. ONE DIRECTION.')}<div class=\"section-heading showcase-heading\"><div>${eyebrow('THE POWER OF CONNECTION')}<h2>Everything you need.<br><span class=\"muted\">Working together.</span></h2></div><p>Great things happen when the right<br>capabilities connect. Discover yours.</p></div></div><div class=\"showcase-viewport\" tabindex=\"0\" role=\"region\" aria-label=\"Our six capabilities. Use the previous and next buttons or arrow keys to explore.\"><div class=\"showcase-track\">${services.map((s,i) => `<article class=\"showcase-card\" data-capability=\"${s.type}\" style=\"--capability-hue:${[272,216,193,306,267,175][i]}\"><div class=\"showcase-card-header\"><span>0${i+1} / 06</span><span>${icons[s.icon]}</span></div>${serviceVisual(s.type,'showcase-visual')}<div class=\"showcase-card-content\"><h3>${s.name}</h3><p>${s.short}</p><a class=\"text-link\" href=\"/services/${s.slug}\">Explore capability ${diagonal}</a></div></article>`).join('')}</div></div><div class=\"container showcase-controls\"><span class=\"showcase-hint\">SCROLL TO EXPLORE <span>⟶</span></span><div class=\"showcase-progress\" aria-hidden=\"true\"><i></i></div><div class=\"showcase-buttons\"><button class=\"showcase-prev icon-button\" aria-label=\"Previous capability\">${arrow}</button><button class=\"showcase-next icon-button\" aria-label=\"Next capability\">${arrow}</button></div></div></div></section>`;\n}\n\nfunction process() {\n  return `<section id=\"approach\" class=\"process-section container\">${sectionTop('02','A PURPOSEFUL PROCESS','FROM FIRST CONVERSATION TO WHAT’S NEXT.')}<div class=\"section-heading reveal\"><div>${eyebrow('AMBITION, WITH A PLAN')}<h2>Growth doesn’t happen<br><span class=\"muted\">by accident.</span></h2></div><p>We connect understanding with action.<br>Every stage builds on the last.</p></div><div class=\"process-layout reveal\"><div class=\"process-tabs\" role=\"tablist\" aria-label=\"Our seven-stage growth process\" aria-orientation=\"vertical\">${stages.map((s,i)=>`<button id=\"stage-tab-${i}\" class=\"process-tab ${i===0?'selected':''}\" role=\"tab\" aria-selected=\"${i===0}\" aria-controls=\"stage-panel\" tabindex=\"${i===0?0:-1}\" data-stage=\"${i}\"><span class=\"stage-number\">0${i+1}</span><span>${s.name}</span>${arrow}</button>`).join('')}</div><div id=\"stage-panel\" class=\"process-panel\" role=\"tabpanel\" aria-labelledby=\"stage-tab-0\" tabindex=\"0\">${processPanel(0)}</div></div></section>`;\n}\nfunction processPanel(index) {\n  const s=stages[index];\n  return `<div class=\"process-panel-top\"><span>THE AVENTRIXX METHOD</span><span>0${index+1} / 07</span></div><div class=\"process-orbit\" aria-hidden=\"true\"><div></div><div></div><div></div><span>${String(index+1).padStart(2,'0')}</span></div><div class=\"process-panel-copy\"><h3>${s.title}</h3><p>${s.text}</p><div class=\"deliverable-chips\">${s.items.map(x=>`<span>${icons.check}${x}</span>`).join('')}</div></div>`;\n}\n\nfunction aiSection() {\n  return `<section class=\"ai-section\"><div class=\"container\">${sectionTop('03','INTELLIGENCE, ORCHESTRATED','HUMAN VISION. CONNECTED WORKFLOWS.')}<div class=\"ai-layout\"><div class=\"ai-copy reveal\">${eyebrow('INTELLIGENCE WITH INTENTION')}<h2>More than tools.<br><span class=\"text-gradient\">A connected mind.</span></h2><p>Research becomes insight. Insight becomes action. We design AI-assisted workflows that connect the work, with your people in control.</p><a class=\"text-link\" href=\"/services/agentic-ai-marketing\">Discover agentic AI marketing ${diagonal}</a><div class=\"ai-note\">${icons.network}<span>WORKFLOW DEMONSTRATION<br><small>Illustrative architecture. Human oversight at every stage.</small></span></div></div><div class=\"agent-interactive reveal\"><div class=\"agent-diagram\"><svg class=\"agent-connections\" viewBox=\"0 0 580 410\" aria-hidden=\"true\"><defs><radialGradient id=\"networkGlow\"><stop stop-color=\"#b18be9\" stop-opacity=\".24\"/><stop offset=\"1\" stop-color=\"#b18be9\" stop-opacity=\"0\"/></radialGradient></defs><circle cx=\"290\" cy=\"205\" r=\"180\" fill=\"url(#networkGlow)\"/><circle cx=\"290\" cy=\"205\" r=\"146\" fill=\"none\" stroke=\"#9d7fc6\" stroke-opacity=\".15\" stroke-dasharray=\"3 7\"/><path class=\"network-lines\" d=\"M100 110 290 205 480 110M100 300 290 205 480 300M290 45v320\" fill=\"none\" stroke=\"#9570c8\" stroke-opacity=\".5\"/></svg><div class=\"agent-core\">${logo}<span>AVENTRIXX</span><small>HUMAN GUIDED</small></div>${agents.map((a,i)=>`<button class=\"agent-node agent-node-${i} ${i===0?'selected':''}\" data-agent=\"${i}\" aria-pressed=\"${i===0}\" aria-controls=\"agent-description\">${icons[a.icon]}<span>${a.name}</span><i></i></button>`).join('')}</div><div id=\"agent-description\" class=\"agent-description\" aria-live=\"polite\">${agentDescription(0)}</div><span class=\"agent-instruction\">SELECT A NODE TO EXPLORE THE WORKFLOW</span></div></div></div></section>`;\n}\nfunction agentDescription(index) {\n  const a=agents[index];\n  return `<div><span class=\"tiny-dot violet\"></span><strong>0${index+1} · ${a.name}</strong><span>WORKFLOW CONCEPT</span></div><p>${a.text}</p><small>${a.output}</small>`;\n}\n\nfunction projectCards() {\n  return projects.map((p,i)=>`<a class=\"project-card reveal\" href=\"/work/${p.slug}\" style=\"--reveal-delay:${i*70}ms\"><div class=\"project-visual project-${p.slug}\"><span class=\"concept-label\">CONCEPT PROJECT</span>${serviceVisual(p.type,'portfolio-visual')}<div class=\"project-overlay\"><span>${p.name}</span>${diagonal}</div></div><div class=\"project-info\"><h3>${p.name}</h3><span>${p.category}</span>${diagonal}</div></a>`).join('');\n}\n\nfunction home() {\n  return `<main id=\"main\">${referenceHero()}${unlockSection()}${showcase()}${experienceSection()}${process()}${aiSection()}<section class=\"work-section container\">${sectionTop('04','POSSIBILITY, MADE VISIBLE','A GLIMPSE OF WHAT WE CAN CREATE.')}<div class=\"section-heading reveal\"><div>${eyebrow('SELECTED EXPLORATIONS')}<h2>Ideas with intention.<br><span class=\"muted\">Experiences with impact.</span></h2></div><a class=\"text-link\" href=\"/work\">Explore selected work ${diagonal}</a></div><div class=\"project-grid\">${projectCards()}</div><p class=\"concept-note\">An exploration of our approach. These are concept projects, not commissioned client work.</p></section><section class=\"principles-section container reveal\"><div>${eyebrow('THE WAY WE THINK')}<h2>Purpose over noise.<br><span class=\"muted\">Progress over promises.</span></h2></div><div class=\"principles-list\"><div><span>01</span><h3>Clarity comes first.</h3><p>Understand the business before choosing the tools.</p></div><div><span>02</span><h3>Everything connects.</h3><p>Design, data, and marketing move in one direction.</p></div><div><span>03</span><h3>People stay at the center.</h3><p>Technology supports judgment. It never replaces trust.</p></div></div></section>${journalSection()}${cta()}</main>`;\n}\n\nfunction servicesPage() {\n  return `<main id=\"main\"><section class=\"page-hero container\">${eyebrow('CONNECTED CAPABILITIES')}<h1>Six perspectives.<br><span class=\"text-gradient\">One growth system.</span></h1><p>Strategy, design, intelligence, and technology.<br>The right combination for your next chapter.</p></section><section class=\"container services-grid\">${capabilityCards()}</section><section class=\"services-story container reveal\"><h2>Start with your ambition.<br><span class=\"muted\">We’ll find the right combination.</span></h2><p>You don’t need to choose every service. We begin with your business and build a focused roadmap around what will be most useful.</p>${button('Build My Growth Strategy')}</section>${aiSection()}${cta()}</main>`;\n}\nfunction servicePage(service) {\n  const related=services.filter(s=>s.slug!==service.slug).slice(0,3);\n  return `<main id=\"main\"><section class=\"service-hero container\"><div><a class=\"breadcrumb\" href=\"/services\">← ALL CAPABILITIES</a>${eyebrow(service.name.toUpperCase())}<h1>${service.title}</h1><p>${service.description}</p>${button('Build My Growth Strategy',`/contact?service=${service.slug}`)}</div>${serviceVisual(service.type,'detail-visual')}</section><section class=\"service-details container\"><div class=\"reveal\">${eyebrow('PURPOSE BEFORE PROCESS')}<h2>${service.short}</h2><p>${service.detail}</p></div><div class=\"deliverables-panel reveal\"><h3>What we can help you build</h3>${service.deliverables.map((d,i)=>`<div><span>0${i+1}</span><p>${d}</p>${icons.check}</div>`).join('')}<small>Deliverables and scope are agreed for each engagement.</small></div></section>${service.type==='ai'?aiSection():''}${service.type==='growth'?`<section class=\"container data-disclaimer\">${icons.chart}<p>The dashboard above uses illustrative data to demonstrate a possible reporting interface. These figures are not client outcomes, forecasts, or guarantees.</p></section>`:''}<section class=\"container related-section\">${eyebrow('BETTER, TOGETHER')}<h2>Connect your next capability.</h2><div class=\"related-grid\">${related.map(s=>`<a class=\"service-card\" href=\"/services/${s.slug}\"><span class=\"service-icon\">${icons[s.icon]}</span><h3>${s.name}</h3><p>${s.short}</p><div class=\"card-bottom\"><span>Explore capability</span>${diagonal}</div></a>`).join('')}</div></section>${cta()}</main>`;\n}\nfunction workPage() {\n  return `<main id=\"main\"><section class=\"page-hero container\">${eyebrow('SELECTED EXPLORATIONS')}<h1>Possibility,<br><span class=\"text-gradient\">made visible.</span></h1><p>A collection of concept experiences that explore<br>how thoughtful design and intelligent technology connect.</p></section><section class=\"container work-list\"><div class=\"project-grid\">${projectCards()}</div><p class=\"concept-note\">All projects on this page are self-initiated concepts. No client relationships or business results are implied.</p></section>${cta()}</main>`;\n}\nfunction projectPage(project) {\n  return `<main id=\"main\"><section class=\"page-hero container\"><a class=\"breadcrumb\" href=\"/work\">← ALL EXPLORATIONS</a>${eyebrow(`${project.category} / CONCEPT PROJECT`)}<h1>${project.name}<span class=\"text-gradient\">.</span></h1><p>${project.title}</p></section><section class=\"container case-visual project-${project.slug}\">${serviceVisual(project.type,'case-study-visual')}<span class=\"concept-label\">SELF-INITIATED CONCEPT · DEMONSTRATION ONLY</span></section><section class=\"case-details container\"><div>${eyebrow('THE EXPLORATION')}<h2>A considered approach.</h2><div class=\"deliverable-chips\">${project.tags.map(t=>`<span>${t}</span>`).join('')}</div></div><div><h3>The design challenge</h3><p>${project.challenge}</p><h3>The approach</h3><p>${project.approach}</p><h3>About this concept</h3><p>This is an illustrative design exploration. It is not commissioned client work, and no performance outcomes are claimed.</p></div></section><div class=\"container case-navigation\"><a class=\"text-link\" href=\"/work\">← Back to selected work</a><a class=\"text-link\" href=\"/work/${projects[(projects.indexOf(project)+1)%projects.length].slug}\">Next exploration ${arrow}</a></div>${cta()}</main>`;\n}\nfunction aboutPage() {\n  return `<main id=\"main\"><section class=\"page-hero container\">${eyebrow('ABOUT AVENTRIXX')}<h1>Different disciplines.<br><span class=\"text-gradient\">Shared ambition.</span></h1><p>A creative technology and growth studio connecting<br>digital experiences, market intelligence, and purposeful AI.</p></section><section class=\"about-manifesto container reveal\"><span class=\"about-symbol\" aria-hidden=\"true\">✳</span><div><h2>We see the bigger picture.<br><span class=\"muted\">Then we build the connections.</span></h2><p>Too often, businesses get a website without a strategy, marketing without insight, or technology without purpose. Aventrixx brings those pieces together.</p><p>Our approach starts with your business. We listen, investigate, and build a clear direction before choosing the tools. Every design decision and every workflow should make your business easier to discover, understand, and connect with.</p><p>We believe in honest expectations, useful technology, and progress you can understand. AI supports the work. Human judgment guides it.</p></div></section>${process()}${cta()}</main>`;\n}\n\nfunction contactPage() {\n  const selected = new URLSearchParams(location.search).get('service');\n  return `<main id=\"main\"><section class=\"contact-section container\"><div class=\"contact-copy\">${eyebrow('LET’S START A CONVERSATION')}<h1>Your ambition.<br><span class=\"text-gradient\">Our next chapter.</span></h1><p>Tell us a little about your business and what you have in mind. We’ll start with a conversation about where you want to go.</p><div class=\"contact-expectations\"><h2>WHAT HAPPENS NEXT</h2><div><span>01</span><p>We review your business and your inquiry.</p></div><div><span>02</span><p>We contact you to arrange a discovery conversation.</p></div><div><span>03</span><p>Together, we define a practical next step.</p></div></div><span class=\"contact-status\"><span class=\"status-dot\"></span> A thoughtful conversation. No pressure.</span></div><form id=\"inquiry-form\" class=\"inquiry-form\"><span class=\"form-label\">BUILD MY GROWTH STRATEGY</span><h2>Let’s get to know you.</h2><div class=\"form-row\"><label>Your name <span>*</span><input name=\"name\" autocomplete=\"name\" placeholder=\"Alex Morgan\" required minlength=\"2\" maxlength=\"100\"></label><label>Work email <span>*</span><input name=\"email\" autocomplete=\"email\" type=\"email\" placeholder=\"alex@yourcompany.com\" required maxlength=\"254\"></label></div><label>Company / website<input name=\"company\" autocomplete=\"organization\" placeholder=\"Your business name or website\" maxlength=\"200\"></label><label>What are you interested in? <span>*</span><select name=\"service\" required><option value=\"Growth strategy\">An integrated growth strategy</option>${services.map(s=>`<option value=\"${s.name}\" ${s.slug===selected?'selected':''}>${s.name}</option>`).join('')}<option value=\"Not sure yet\">I’d like some guidance</option></select></label><label>Tell us about your ambition <span>*</span><textarea name=\"message\" rows=\"5\" placeholder=\"What does your business do? What would you like to achieve?\" required minlength=\"20\" maxlength=\"5000\"></textarea><small>A little context helps us prepare. At least 20 characters.</small></label><div class=\"honeypot\" aria-hidden=\"true\"><label>Leave this field empty<input name=\"website_check\" tabindex=\"-1\" autocomplete=\"off\"></label></div><label class=\"consent-label\"><input type=\"checkbox\" name=\"consent\" required><span>I agree to Aventrixx storing my information and contacting me about this inquiry. Read the <a href=\"/privacy\">privacy policy</a>.</span></label><button class=\"button button-primary form-submit\" type=\"submit\"><span>Send My Inquiry</span>${arrow}</button><div id=\"form-status\" class=\"form-status\" role=\"status\" aria-live=\"polite\"></div><span class=\"form-footnote\">Your information is used to handle your inquiry. We won’t add you to a mailing list.</span></form></section></main>`;\n}\n\nfunction legalPage(type) {\n  const privacy=type==='privacy';\n  return `<main id=\"main\"><section class=\"page-hero container\">${eyebrow('AVENTRIXX / LEGAL')}<h1>${privacy?'Privacy policy':'Terms of use'}<span class=\"text-gradient\">.</span></h1><p>Last updated: October 21, 2026</p></section><article class=\"legal-copy container\">${privacy?`<h2>Information you share</h2><p>When you submit an inquiry, we collect your name, email address, company or website if provided, service interest, message, and your consent. Please avoid submitting sensitive personal information.</p><h2>How it is used</h2><p>Your information is used to review your inquiry, respond to you, and discuss a potential engagement. It is not used to subscribe you to marketing emails or sold to third parties.</p><h2>Storage and security</h2><p>Inquiries are stored on the server hosting this website. Network address information is temporarily held in memory for rate limiting and spam protection and is not included in the inquiry record. Server operators may maintain technical access logs. Access to inquiry records should be restricted to authorized personnel.</p><h2>Retention</h2><p>Inquiry records are retained for up to 12 months and then deleted automatically when the server runs. If an engagement follows, any additional processing and retention terms will be agreed separately.</p><h2>Cookies and analytics</h2><p>This site does not set advertising cookies or include third-party analytics. Essential browser storage may be used to preserve navigation behavior. The visual dashboards use illustrative data.</p><h2>Your choices</h2><p>You may request access, correction, or deletion of your inquiry data through the <a href=\"/contact\">contact form</a>. Include enough information for us to identify your inquiry without submitting sensitive documents.</p>`:`<h2>Using this website</h2><p>This website introduces Aventrixx’s approach and capabilities. Service descriptions are general information. Scope, availability, deliverables, pricing, and obligations are established in a separate written engagement agreement.</p><h2>Concepts and demonstration data</h2><p>Portfolio concepts and interface demonstrations are clearly labeled. They do not represent commissioned client work, actual client metrics, guaranteed outcomes, or a live autonomous AI system.</p><h2>No performance guarantees</h2><p>Marketing, search visibility, and business outcomes depend on many factors outside any studio’s control. Nothing on this website guarantees rankings, revenue, leads, or specific business results.</p><h2>Intellectual property</h2><p>The Aventrixx identity, original website design, and concept materials may not be reproduced for commercial use without authorization. Any third-party rights remain with their respective owners.</p><h2>Inquiries</h2><p>Submitting an inquiry does not create a service agreement or guarantee availability. We use your submitted details to review and respond to your request, in accordance with our <a href=\"/privacy\">privacy policy</a>.</p><h2>Contact</h2><p>For questions about these terms, use the <a href=\"/contact\">contact form</a>.</p>`}</article></main>`;\n}\nfunction notFound() {\n  return `<main id=\"main\"><section class=\"page-hero container error-page\">${eyebrow('404 / A DIFFERENT DIRECTION')}<h1>A little off course.<br><span class=\"text-gradient\">Let’s reconnect.</span></h1><p>The page you’re looking for isn’t here.</p>${button('Back to Aventrixx','/')}</section></main>`;\n}\n\nfunction render({scroll=true}={}) {\n  cleanupMotion();\n  pageAbort?.abort();\n  pageAbort=new AbortController();\n  document.body.classList.remove('menu-open');\n  const path=location.pathname.replace(/\\/$/,'')||'/';\n  let content, title;\n  const studio=renderStudio(path);\n  if(studio){content=studio.html;title=studio.title;}\n  else if(path==='/'){content=home();title='Beyond presence. Into possibility.';}\n  else if(path==='/services'){content=servicesPage();title='Our Capabilities';}\n  else if(path.startsWith('/services/')){const s=services.find(s=>`/services/${s.slug}`===path);content=s?servicePage(s):notFound();title=s?s.name:'Page not found';}\n  else if(path==='/work'){content=workPage();title='Selected Explorations';}\n  else if(path.startsWith('/work/')){const p=projects.find(p=>`/work/${p.slug}`===path);content=p?projectPage(p):notFound();title=p?p.name:'Page not found';}\n  else if(path==='/about'){content=aboutPage();title='About Us';}\n  else if(path==='/contact'){content=contactPage();title='Build My Growth Strategy';}\n  else if(path==='/privacy'||path==='/terms'){content=legalPage(path.slice(1));title=path==='/privacy'?'Privacy Policy':'Terms of Use';}\n  else {content=notFound();title='Page not found';}\n  document.title=`Aventrixx — ${title}`;\n  app.innerHTML=header(path)+content+footer();\n  bindPage();\n  if(scroll)window.scrollTo({top:0,behavior:'instant'});\n  cleanupMotion=initMotion();\n  if(location.hash)requestAnimationFrame(()=>hashTarget(location.hash)?.scrollIntoView({behavior:'instant'}));\n}\n\nfunction hashTarget(hash) {\n  try{return document.getElementById(decodeURIComponent(hash.slice(1)));}catch{return null;}\n}\n\nfunction bindPage() {\n  const signal=pageAbort.signal;\n  bindExperience(signal);\n  bindStudio(signal);\n  const on=(el,event,handler)=>el?.addEventListener(event,handler,{signal});\n  const toggle=document.querySelector('.dropdown-toggle'), menu=document.querySelector('.dropdown-menu');\n  const setDropdown=(open)=>{toggle.setAttribute('aria-expanded',String(open));menu.hidden=!open;};\n  on(toggle,'click',()=>setDropdown(menu.hidden));\n  on(document,'click',e=>{if(!e.target.closest('.nav-dropdown'))setDropdown(false);});\n  on(document.querySelector('.nav-dropdown'),'focusout',e=>{if(!e.currentTarget.contains(e.relatedTarget))setDropdown(false);});\n  const mobileToggle=document.querySelector('.mobile-toggle'), mobile=document.querySelector('.mobile-menu');\n  const setMobile=(open)=>{mobile.hidden=!open;mobileToggle.setAttribute('aria-expanded',String(open));mobileToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');document.body.classList.toggle('menu-open',open);if(open)mobile.querySelector('a').focus();};\n  on(mobileToggle,'click',()=>setMobile(mobile.hidden));\n  on(document,'keydown',e=>{\n    if(e.key==='Escape'){if(!menu.hidden){setDropdown(false);toggle.focus();}if(!mobile.hidden){setMobile(false);mobileToggle.focus();}}\n    if(e.key==='Tab'&&!mobile.hidden){const els=[mobileToggle,...mobile.querySelectorAll('a')];const current=els.indexOf(document.activeElement);if(e.shiftKey&&current===0){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&current===els.length-1){e.preventDefault();mobileToggle.focus();}}\n  });\n  const processTabs=[...document.querySelectorAll('.process-tab')];\n  function selectStage(index,focus=false){processTabs.forEach((t,i)=>{t.classList.toggle('selected',i===index);t.setAttribute('aria-selected',String(i===index));t.tabIndex=i===index?0:-1;});const panel=document.querySelector('#stage-panel');panel.innerHTML=processPanel(index);panel.setAttribute('aria-labelledby',`stage-tab-${index}`);if(focus)processTabs[index].focus();}\n  processTabs.forEach((tab,index)=>{on(tab,'click',()=>selectStage(index));on(tab,'keydown',e=>{let next=index;if(e.key==='ArrowDown'||e.key==='ArrowRight')next=(index+1)%stages.length;else if(e.key==='ArrowUp'||e.key==='ArrowLeft')next=(index+stages.length-1)%stages.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=stages.length-1;else return;e.preventDefault();selectStage(next,true);});});\n  document.querySelectorAll('.agent-node').forEach(node=>on(node,'click',()=>{const index=Number(node.dataset.agent);document.querySelectorAll('.agent-node').forEach(n=>{const selected=n===node;n.classList.toggle('selected',selected);n.setAttribute('aria-pressed',String(selected));});document.querySelector('#agent-description').innerHTML=agentDescription(index);}));\n  on(document.querySelector('.back-top'),'click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));\n  on(document.querySelector('#inquiry-form'),'submit',submitInquiry);\n}\n\nasync function submitInquiry(event) {\n  event.preventDefault();\n  const form=event.currentTarget;\n  if(!form.reportValidity())return;\n  const status=form.querySelector('#form-status'),submit=form.querySelector('.form-submit');\n  const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;\n  status.className='form-status';status.textContent='Sending your inquiry…';submit.disabled=true;submit.querySelector('span').textContent='Sending…';\n  try {\n    const response=await fetch('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(15000)});\n    const result=await response.json();\n    if(!response.ok)throw new Error(result.error||'Your inquiry could not be saved. Please try again.');\n    status.classList.add('success');status.textContent=`Your inquiry has been received. Reference: ${result.reference}. We’ll use your email to discuss a discovery conversation.`;form.reset();submit.querySelector('span').textContent='Send Another Inquiry';\n  } catch(error) {\n    status.classList.add('error');status.textContent=error.name==='TimeoutError'?'The request timed out and delivery is uncertain. Please try again if needed.':error.message==='Failed to fetch'?'We couldn’t reach the server. Your inquiry has not been confirmed; please try again.':error.message;submit.querySelector('span').textContent='Try Again';\n  } finally {submit.disabled=false;}\n}\n\ndocument.addEventListener('click',event=>{\n  const link=event.target.closest('a');\n  if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||link.target||link.hasAttribute('download'))return;\n  const url=new URL(link.href,location.href);\n  if(url.origin!==location.origin)return;\n  event.preventDefault();\n  const samePage=url.pathname===location.pathname&&url.search===location.search;\n  if(samePage&&url.hash){history.pushState({},'',url);hashTarget(url.hash)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('.mobile-menu').hidden=true;document.querySelector('.mobile-toggle').setAttribute('aria-expanded','false');document.querySelector('.mobile-toggle').setAttribute('aria-label','Open navigation');document.body.classList.remove('menu-open');return;}\n  history.pushState({},'',url);render();\n  const main=document.querySelector('#main');main.setAttribute('tabindex','-1');main.focus({preventScroll:true});\n});\nhistory.scrollRestoration='auto';\nwindow.addEventListener('popstate',()=>render({scroll:false}));\nrender({scroll:false});\n");
embeddedAssets.set("/src/visuals.js", "export const icons = {\n  arrow: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"M5 12h14m-6-6 6 6-6 6\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  diagonal: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"M6 18 18 6M6 6h12v12\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  plus: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg>',\n  check: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m5 12 4 4L19 6\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  globe: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\" stroke=\"currentColor\" stroke-width=\"1.4\"/><ellipse cx=\"12\" cy=\"12\" rx=\"4\" ry=\"9\" stroke=\"currentColor\" stroke-width=\"1.4\"/><path d=\"M3 12h18\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg>',\n  chart: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"M4 4v16h16M8 15l4-5 4 2 4-7\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  search: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\" stroke=\"currentColor\" stroke-width=\"1.4\"/><path d=\"m16 16 5 5\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg>',\n  target: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"12\" cy=\"12\" r=\"5\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"currentColor\"/></svg>',\n  network: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m6 6 6 6 6-6M6 18l6-6 6 6\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"5\" cy=\"5\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"19\" cy=\"5\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"5\" cy=\"19\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"19\" cy=\"19\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"12\" cy=\"12\" r=\"2\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg>',\n  growth: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m3 17 6-6 4 4 8-10M14 5h7v7\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>'\n};\nexport const logo = '<svg class=\"brand-mark\" viewBox=\"0 0 36 36\" fill=\"none\" aria-hidden=\"true\"><path d=\"M3 29 15 6h6l12 23H23l-5-11-5 11Z\" fill=\"currentColor\"/><path d=\"m15 28 3-6 3 6Z\" fill=\"currentColor\"/></svg>';\n\nfunction lightSculpture() {\n  // Project a shaded tube mesh into SVG, then paint its faces from back to front.\n  const steps=160,sides=16;\n  const unit=v=>{const length=Math.hypot(...v);return v.map(x=>x/length);};\n  const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];\n  const curve=t=>{const radius=1.7+.58*Math.cos(3*t);return [radius*Math.cos(2*t),radius*Math.sin(2*t),.58*Math.sin(3*t)];};\n  const rotate=([x,y,z])=>{const px=x*Math.cos(.7)+z*Math.sin(.7),pz=-x*Math.sin(.7)+z*Math.cos(.7);return [px,y*Math.cos(.78)-pz*Math.sin(.78),y*Math.sin(.78)+pz*Math.cos(.78)];};\n  const light=unit([-.45,-.7,1]);\n  const rings=Array.from({length:steps},(_,i)=>{\n    const t=i/steps*Math.PI*2,center=curve(t),next=curve(t+.001);\n    const tangent=unit(next.map((n,j)=>n-center[j]));\n    const normal=unit(cross(tangent,[0,0,1])),binormal=unit(cross(tangent,normal));\n    return Array.from({length:sides},(_,j)=>{\n      const angle=j/sides*Math.PI*2;\n      const surface=normal.map((n,k)=>n*Math.cos(angle)+binormal[k]*Math.sin(angle));\n      const position=rotate(center.map((n,k)=>n+surface[k]*.19));\n      const worldNormal=rotate(surface);\n      const diffuse=Math.max(0,worldNormal.reduce((sum,n,k)=>sum+n*light[k],0));\n      const reflection=Math.pow(diffuse,7);\n      return {x:320+position[0]*84,y:310+position[1]*84,z:position[2],shade:27+diffuse*35+reflection*24};\n    });\n  });\n  const faces=[];\n  for(let i=0;i<steps;i++)for(let j=0;j<sides;j++){\n    const vertices=[rings[i][j],rings[(i+1)%steps][j],rings[(i+1)%steps][(j+1)%sides],rings[i][(j+1)%sides]];\n    faces.push({vertices,depth:vertices.reduce((sum,v)=>sum+v.z,0)/4,shade:vertices.reduce((sum,v)=>sum+v.shade,0)/4});\n  }\n  return faces.sort((a,b)=>a.depth-b.depth).map(({vertices,depth,shade})=>{\n    const color=`hsl(${270+depth*4} ${Math.round(45-(shade-27)*.25)}% ${Math.round(shade)}%)`;\n    return `<polygon points=\"${vertices.map(v=>`${v.x.toFixed(1)},${v.y.toFixed(1)}`).join(' ')}\" fill=\"${color}\" stroke=\"${color}\" stroke-width=\".45\" stroke-linejoin=\"round\"/>`;\n  }).join('');\n}\n\nexport function heroArt() {\n  return `<div class=\"hero-art\" aria-label=\"An interconnected growth system, illustrated by luminous orbital paths\">\n    <div class=\"art-grid\"></div><div class=\"art-halo\"></div><div class=\"art-aura aura-one\"></div><div class=\"art-aura aura-two\"></div>\n    <svg class=\"orbital-art\" viewBox=\"0 0 640 620\" fill=\"none\" aria-hidden=\"true\">\n      <defs><linearGradient id=\"orbitGradient\" x1=\"100\" y1=\"120\" x2=\"530\" y2=\"510\" gradientUnits=\"userSpaceOnUse\"><stop stop-color=\"#d8c7ff\"/><stop offset=\".4\" stop-color=\"#8057de\"/><stop offset=\"1\" stop-color=\"#337ea2\"/></linearGradient><radialGradient id=\"coreGradient\"><stop stop-color=\"#dfceff\"/><stop offset=\".2\" stop-color=\"#b999f3\"/><stop offset=\".75\" stop-color=\"#513777\"/><stop offset=\"1\" stop-color=\"#171022\"/></radialGradient><linearGradient id=\"ribbonGradient\" x1=\"202\" y1=\"130\" x2=\"420\" y2=\"450\"><stop stop-color=\"#eee5ff\"/><stop offset=\".28\" stop-color=\"#bd94ff\"/><stop offset=\".6\" stop-color=\"#8054cc\"/><stop offset=\"1\" stop-color=\"#302342\"/></linearGradient><filter id=\"glow\"><feGaussianBlur stdDeviation=\"4\"/></filter></defs>\n      <g class=\"orbit-slow\"><ellipse cx=\"320\" cy=\"310\" rx=\"273\" ry=\"115\" transform=\"rotate(-32 320 310)\" stroke=\"url(#orbitGradient)\" stroke-opacity=\".5\"/><ellipse cx=\"320\" cy=\"310\" rx=\"237\" ry=\"174\" transform=\"rotate(40 320 310)\" stroke=\"url(#orbitGradient)\" stroke-opacity=\".28\"/><ellipse cx=\"320\" cy=\"310\" rx=\"145\" ry=\"247\" transform=\"rotate(-32 320 310)\" stroke=\"url(#orbitGradient)\" stroke-opacity=\".35\"/></g>\n      <ellipse cx=\"320\" cy=\"310\" rx=\"276\" ry=\"255\" stroke=\"#b79de4\" stroke-opacity=\".08\" stroke-dasharray=\"3 8\"/>\n      <path d=\"M113 396C187 420 265 402 368 339S532 205 531 177\" stroke=\"url(#orbitGradient)\" stroke-width=\"2\"/>\n      <g class=\"core-shape\">${lightSculpture()}</g>\n      <ellipse class=\"orbit-signal\" cx=\"320\" cy=\"310\" rx=\"273\" ry=\"115\" transform=\"rotate(-32 320 310)\" stroke=\"#dec7ff\" stroke-width=\"2\" stroke-dasharray=\"12 1250\" stroke-linecap=\"round\"/>\n      <circle cx=\"113\" cy=\"396\" r=\"5\" fill=\"#b992ff\"/><circle cx=\"113\" cy=\"396\" r=\"11\" stroke=\"#b992ff\" stroke-opacity=\".3\"/><circle cx=\"531\" cy=\"177\" r=\"4\" fill=\"#b5dfff\"/><circle cx=\"531\" cy=\"177\" r=\"10\" stroke=\"#b5dfff\" stroke-opacity=\".25\"/><circle cx=\"416\" cy=\"519\" r=\"3\" fill=\"#9a74de\"/><circle cx=\"204\" cy=\"84\" r=\"3\" fill=\"#9a74de\"/>\n      <path d=\"M320 38v12m-6-6h12M574 356v12m-6-6h12M64 239v12m-6-6h12\" stroke=\"#87769d\" stroke-opacity=\".6\"/>\n    </svg>\n    <div class=\"orbit-label label-strategy\"><span class=\"tiny-dot violet\"></span> STRATEGY <span class=\"label-coordinate\">01</span></div>\n    <div class=\"orbit-label label-intelligence\"><span class=\"tiny-dot cyan\"></span> INTELLIGENCE <span class=\"label-coordinate\">02</span></div>\n    <div class=\"orbit-label label-growth\"><span class=\"tiny-dot\"></span> GROWTH <span class=\"label-coordinate\">03</span></div>\n    <div class=\"art-caption\"><span class=\"status-dot\"></span> CONNECTION CREATES POSSIBILITY <span>↗</span></div><span class=\"art-index\" aria-hidden=\"true\">FIG. 001 — THE CONNECTED SYSTEM</span>\n  </div>`;\n}\n\nexport function comparisonVisual() {\n  return `<div class=\"design-comparison\" style=\"--comparison:68%\">\n    <div class=\"comparison-base\" aria-hidden=\"true\"><div class=\"basic-site\"><div class=\"basic-nav\"><strong>FORM & FIELD</strong><span>Home &nbsp; Products &nbsp; About</span></div><div class=\"basic-hero\"><span>WELCOME TO OUR WEBSITE</span><strong>Quality furniture<br>for your home.</strong><p>Browse our furniture collection.<br>Beautiful products for every space.</p><span class=\"basic-button\">VIEW PRODUCTS</span></div><div class=\"basic-products\"><i></i><i></i><i></i></div></div></div>\n    <div class=\"comparison-enhanced\" aria-hidden=\"true\"><div class=\"designed-site\"><div class=\"designed-nav\"><b>form<span>&</span>field</b><span>Objects &nbsp; Our story &nbsp; ↗</span></div><div class=\"designed-content\"><div><span class=\"designed-kicker\">A QUIETER KIND OF EXTRAORDINARY</span><strong>Objects.<br>With <em>soul.</em></strong><p>Thoughtful forms. Honest materials.<br>Designed for a life well lived.</p><span class=\"designed-button\">Explore the collection <span>↗</span></span></div><div class=\"art-object\"><div class=\"object-shadow\"></div><div class=\"object-ring ring-a\"></div><div class=\"object-ring ring-b\"></div><div class=\"object-ring ring-c\"></div><span class=\"object-pedestal\"></span><i class=\"object-caption\">NO. 01 / THE CONTINUUM</i></div></div><div class=\"designed-footer\"><span>LESS, BUT BETTER.</span><span>EST. 2026 &nbsp; · &nbsp; MADE WITH INTENTION</span></div></div></div>\n    <div class=\"comparison-divider\" aria-hidden=\"true\"><span>‹ &nbsp; ›</span></div>\n    <input class=\"comparison-range\" type=\"range\" min=\"0\" max=\"100\" value=\"68\" aria-label=\"Reveal the considered design\" aria-valuetext=\"68 percent considered design visible\" />\n    <div class=\"comparison-labels\" aria-hidden=\"true\"><span>CONSIDERED DESIGN</span><span>BASIC TEMPLATE</span></div>\n  </div>`;\n}\n\nconst windowBar = (label) => `<div class=\"window-bar\"><span class=\"window-dots\"><i></i><i></i><i></i></span><span>${label}</span><span>↗</span></div>`;\nexport function serviceVisual(type, variant = '') {\n  let content = '';\n  if (type === 'presence') content = `<div class=\"browser secondary-browser\">${windowBar('MOBILE / RESPONSIVE')}<div class=\"mobile-preview\"><span>STUDIO NORTH</span><div class=\"mini-sculpture\"></div><strong>A different<br>perspective.</strong><i>Explore the collection ↗</i></div></div><div class=\"browser main-browser\">${windowBar('DIGITAL EXPERIENCE')}<div class=\"website-preview\"><div class=\"preview-nav\"><b>FORM & FIELD</b><span>Collection &nbsp; Studio &nbsp; ↗</span></div><div class=\"preview-hero\"><div><span>OBJECTS WITH INTENTION</span><strong>Made to<br>mean more.</strong><i>Discover the collection ↗</i></div><div class=\"sculpture\"><i></i><i></i><i></i></div></div><div class=\"preview-bottom\">Thoughtful design. Lasting impact. <span>01 / 03</span></div></div></div><span class=\"floating-tag\">${icons.check} Responsive by design</span>`;\n  if (type === 'intelligence') content = `<div class=\"browser analytics-browser\">${windowBar('MARKET INTELLIGENCE')}<div class=\"dashboard-body\"><div class=\"dashboard-heading\"><span>Opportunity landscape</span><small>DEMO DATA</small></div><div class=\"chart-legend\"><span><i></i>Your audience</span><span><i></i>Market demand</span></div><svg class=\"line-chart\" viewBox=\"0 0 400 150\" fill=\"none\" aria-hidden=\"true\"><path d=\"M0 30h400M0 70h400M0 110h400\" stroke=\"#ffffff\" stroke-opacity=\".06\"/><path class=\"draw-path\" d=\"M0 130C35 125 35 65 75 83S135 120 170 67s70 15 100-21 55 5 80-25 40-12 50-20\" stroke=\"#b39ae9\" stroke-width=\"3\"/><path d=\"M0 140c60-10 85-30 130-20s70-53 120-43 90-39 150-43\" stroke=\"#619ca7\" stroke-width=\"2\" stroke-dasharray=\"5 5\"/></svg><div class=\"segment-grid\"><div><span>01</span><b>Audience</b><small>Intent & behavior</small></div><div><span>02</span><b>Competition</b><small>Position & opportunity</small></div><div><span>03</span><b>Demand</b><small>Trends & signals</small></div></div></div></div><span class=\"floating-tag\">${icons.search} Clarity before action</span>`;\n  if (type === 'search') content = `<div class=\"browser search-browser\">${windowBar('SEARCH VISIBILITY')}<div class=\"dashboard-body\"><div class=\"search-field\">${icons.search}<span>Make your business discoverable</span><span class=\"search-key\">↵</span></div><div class=\"search-result\"><small>YOUR BUSINESS · EXAMPLE.COM</small><strong>Meet your audience where they search.</strong><p>Useful content. A healthy website. A clear path from discovery to action.</p></div><div class=\"audit-list\"><div><span>${icons.check} Technical foundations</span><b>Structured</b></div><div><span>${icons.check} Content architecture</span><b>Connected</b></div><div><span>${icons.check} Customer search intent</span><b>Mapped</b></div></div><div class=\"keyword-chips\"><span>Technical SEO</span><span>Search intent</span><span>Content strategy</span></div></div></div><span class=\"floating-tag\">${icons.globe} Built to be found</span>`;\n  if (type === 'acquisition') content = `<div class=\"browser funnel-browser\">${windowBar('CUSTOMER JOURNEY')}<div class=\"dashboard-body\"><div class=\"dashboard-heading\"><span>From interest to intent</span><small>WORKFLOW CONCEPT</small></div><div class=\"funnel-flow\"><div><i>01</i><strong>Discover</strong><span>The right audience</span></div><span class=\"flow-connector\"></span><div><i>02</i><strong>Connect</strong><span>A relevant experience</span></div><span class=\"flow-connector\"></span><div><i>03</i><strong>Convert</strong><span>A meaningful next step</span></div></div><div class=\"journey-bottom\">${icons.target}<span>Qualified relationships.<br><b>Built for lasting value.</b></span><span>↗</span></div></div></div><span class=\"floating-tag\">${icons.target} Authentic connections</span>`;\n  if (type === 'ai') content = `<div class=\"browser ai-browser\">${windowBar('AGENTIC MARKETING / CONCEPT')}<div class=\"dashboard-body\"><div class=\"mini-network\"><div class=\"network-center\">${logo}<small>HUMAN GUIDED</small></div><div class=\"mini-node node-one\">${icons.search}<span>Research</span></div><div class=\"mini-node node-two\">${icons.chart}<span>Analyze</span></div><div class=\"mini-node node-three\">${icons.target}<span>Execute</span></div><div class=\"mini-node node-four\">${icons.growth}<span>Optimize</span></div><svg viewBox=\"0 0 400 240\" aria-hidden=\"true\"><path d=\"M80 55 200 120 320 55M80 190 200 120 320 190\" fill=\"none\" stroke=\"#9172c6\" stroke-opacity=\".45\" stroke-dasharray=\"4 5\"/></svg></div><div class=\"network-status\"><span class=\"status-dot\"></span> Connected workflows <span>Human oversight</span></div></div></div><span class=\"floating-tag\">${icons.network} Intelligence, orchestrated</span>`;\n  if (type === 'growth') content = `<div class=\"browser growth-browser\">${windowBar('GROWTH OVERVIEW')}<div class=\"dashboard-body\"><div class=\"dashboard-heading\"><span>The bigger picture</span><small>ILLUSTRATIVE DATA</small></div><div class=\"growth-metrics\"><div><span>Traffic</span><strong>12.8<span>k</span></strong></div><div><span>Qualified leads</span><strong>248</strong></div><div><span>Conversion</span><strong>3.2<span>%</span></strong></div></div><div class=\"bar-chart\">${[22,31,27,40,37,51,46,59,65,62,77,88].map((h,i)=>`<i style=\"--bar-height:${h}%;--bar-delay:${i*40}ms\"></i>`).join('')}</div><div class=\"chart-axis\"><span>JAN</span><span>JUN</span><span>DEC</span></div><div class=\"growth-footnote\">Sample figures explain the interface; they are not client results.</div></div></div><span class=\"floating-tag\">${icons.growth} Progress you can understand</span>`;\n  return `<div class=\"service-visual visual-${type} ${variant}\" aria-label=\"${type === 'growth' || type === 'intelligence' ? 'Illustrative dashboard with sample data' : 'Concept illustration of our service'}\"><div class=\"visual-ambient\"></div><div class=\"visual-grid\"></div>${content}</div>`;\n}\n");
embeddedAssets.set("/src/data.js", "export const services = [\n  { slug: 'digital-presence', type: 'presence', icon: 'globe', name: 'Digital Presence', title: 'A first impression.<br>A lasting advantage.', short: 'Websites with purpose. Experiences with impact.', description: 'Turn your digital presence into your strongest asset. Thoughtful design, intuitive experiences, and the foundations your business needs to move forward.', deliverables: ['Brand-aligned website design', 'Responsive web development', 'Conversion-focused user journeys', 'Performance and accessibility'], detail: 'Your website should express who you are, earn trust, and make the next step feel effortless. We connect brand strategy, design, and development into a digital experience that works as beautifully as it looks.' },\n  { slug: 'market-intelligence', type: 'intelligence', icon: 'chart', name: 'Market Intelligence', title: 'Less guesswork.<br>More perspective.', short: 'Know your market. Find your opportunity.', description: 'Understand the people, patterns, and possibilities behind your next move. Make confident decisions grounded in research, not assumptions.', deliverables: ['Audience and customer research', 'Competitor landscape analysis', 'Market opportunity mapping', 'Actionable strategic recommendations'], detail: 'We investigate your market, your audience, and the competitive landscape to uncover the opportunities that matter. The result is a clear view of where to focus and why.' },\n  { slug: 'search-visibility', type: 'search', icon: 'search', name: 'Search Visibility', title: 'Be there when<br>it matters.', short: 'Discoverability built on strong foundations.', description: 'Connect with customers who are already looking. Bring technical clarity, useful content, and search intent together to build sustainable visibility.', deliverables: ['Technical SEO audits', 'Keyword and intent research', 'Content strategy and architecture', 'Measurement and ongoing refinement'], detail: 'Search visibility starts with a useful, technically sound website. We align content and structure with how your customers search, then measure progress over time. Search outcomes depend on competition, platform changes, and sustained work.' },\n  { slug: 'customer-acquisition', type: 'acquisition', icon: 'target', name: 'Customer Acquisition', title: 'Real connections.<br>Relevant customers.', short: 'Turn the right attention into meaningful action.', description: 'Build a considered path from discovery to conversion. Reach relevant audiences, create useful experiences, and develop relationships that last.', deliverables: ['Audience and channel strategy', 'Landing page development', 'Lead qualification journeys', 'Conversion and retention optimization'], detail: 'More attention is only useful when it brings the right people closer. We create connected acquisition journeys, from the first relevant touchpoint to an informed decision and an ongoing customer relationship.' },\n  { slug: 'agentic-ai-marketing', type: 'ai', icon: 'network', name: 'Agentic AI Marketing', title: 'Connected intelligence.<br>Human direction.', short: 'Purposeful automation. People in control.', description: 'Bring research, planning, and measurement into connected workflows. AI helps with the repetitive work; people guide the strategy and approve the decisions.', deliverables: ['Workflow discovery and design', 'AI-assisted research and analysis', 'Approved tool and system integrations', 'Human review and performance monitoring'], detail: 'We design AI-assisted marketing workflows around your actual processes and approved tools. Each engagement defines the scope, permissions, review points, and integrations before implementation. The visual demonstrations show proposed workflows, not a live autonomous system.' },\n  { slug: 'business-growth', type: 'growth', icon: 'growth', name: 'Intelligent Business Growth', title: 'Connect the dots.<br>See the direction.', short: 'One clear strategy. A business moving forward.', description: 'Bring your digital presence, customer acquisition, and intelligence into one growth system. Measure what matters and refine with purpose.', deliverables: ['Integrated growth roadmap', 'Business and marketing measurement', 'Dashboard and reporting design', 'Ongoing experimentation and optimization'], detail: 'Sustainable growth comes from a connected system. We help you define priorities, connect your marketing and digital infrastructure, and build a practical measurement framework so the next decision is better informed.' }\n];\nexport const stages = [\n  { name: 'Discover', title: 'First, we understand your world.', text: 'Your business, your ambitions, and the challenges standing between them. We start by listening.', items: ['Discovery workshop', 'Business objectives', 'Current-state review'] },\n  { name: 'Analyze', title: 'Find the opportunity in the detail.', text: 'We study your market and customers to understand where meaningful opportunity exists.', items: ['Audience research', 'Competitive landscape', 'Opportunity map'] },\n  { name: 'Strategize', title: 'Give ambition a clear direction.', text: 'We turn research into a practical roadmap with priorities, milestones, and measurable objectives.', items: ['Growth roadmap', 'Channel strategy', 'Measurement plan'] },\n  { name: 'Build', title: 'Create the foundations for what’s next.', text: 'We design and develop the digital infrastructure that brings your strategy to life.', items: ['Digital experience', 'Connected systems', 'Performance foundations'] },\n  { name: 'Attract', title: 'Reach people who see the value.', text: 'Relevant channels and considered journeys help qualified customers discover your business.', items: ['Audience activation', 'Conversion journeys', 'Lead qualification'] },\n  { name: 'Optimize', title: 'Make every iteration more intelligent.', text: 'We combine human judgment and purposeful automation to improve how your growth system works.', items: ['Workflow automation', 'Experimentation', 'Human review'] },\n  { name: 'Scale', title: 'Measure progress. Make the next move.', text: 'We review what the evidence shows and adjust the strategy around your next stage of growth.', items: ['Performance reporting', 'Strategic review', 'Next-stage planning'] }\n];\nexport const agents = [\n  { name: 'Research', icon: 'search', text: 'Gather approved market sources and customer signals into a structured research brief.', output: 'Output: a sourced research brief' },\n  { name: 'Analyze', icon: 'chart', text: 'Compare findings, identify patterns, and surface opportunities for human review.', output: 'Output: reviewed insights and opportunities' },\n  { name: 'Plan', icon: 'target', text: 'Draft a prioritized marketing plan informed by your objectives and research.', output: 'Output: a strategy draft for approval' },\n  { name: 'Execute', icon: 'globe', text: 'Support approved tasks through agreed integrations, with permissions and review points defined first.', output: 'Output: approved workflow tasks' },\n  { name: 'Measure', icon: 'growth', text: 'Bring connected performance data into a consistent, understandable reporting framework.', output: 'Output: a performance summary' },\n  { name: 'Optimize', icon: 'network', text: 'Suggest improvements based on measurement, with a person deciding what happens next.', output: 'Output: recommendations for human approval' }\n];\nexport const projects = [\n  { slug: 'form-and-field', name: 'Form & Field', category: 'DIGITAL EXPERIENCE', type: 'presence', title: 'A considered digital home for a design-led brand.', challenge: 'Explore how an independent furniture studio could translate its material sensibility into a useful online experience.', approach: 'An editorial website concept with purposeful typography, product discovery, and responsive browsing.', tags: ['Experience design', 'E-commerce concept', 'Brand expression'] },\n  { slug: 'signal', name: 'Signal', category: 'INTELLIGENCE & STRATEGY', type: 'intelligence', title: 'Complex information. A clearer perspective.', challenge: 'Explore how market signals and customer research could be made easier to understand and act on.', approach: 'A dashboard concept that connects audience segments, market demand, and a prioritized opportunity landscape.', tags: ['Dashboard design', 'Data visualization', 'Market research'] },\n  { slug: 'nexus', name: 'Nexus', category: 'AI & AUTOMATION', type: 'ai', title: 'A connected workflow with people at its center.', challenge: 'Explore a clear, explainable interface for a marketing workflow supported by multiple AI agents.', approach: 'A workflow concept that makes tasks, handoffs, and human approval points visible at each stage.', tags: ['Workflow design', 'AI-assisted marketing', 'Human oversight'] }\n];\n");
embeddedAssets.set("/src/motion.js", "import { initEffects } from './effects.js';\nimport { initPixelField } from './pixels.js?v=hero-flow-2';\n\nexport function initMotion() {\n  const abort=new AbortController();\n  const {signal}=abort;\n  const reduced=matchMedia('(prefers-reduced-motion: reduce)');\n  const pointer=matchMedia('(hover: hover) and (pointer: fine)');\n  const effects=initEffects({signal,reduced,pointer});\n  const cleanupPixels=initPixelField({signal});\n  const header=document.querySelector('.site-header');\n  const showcase=document.querySelector('.showcase-section');\n  const sticky=showcase?.querySelector('.showcase-sticky');\n  const viewport=showcase?.querySelector('.showcase-viewport');\n  const track=showcase?.querySelector('.showcase-track');\n  const progressBar=showcase?.querySelector('.showcase-progress i');\n  const hero=document.querySelector('.hero');\n  const art=hero?.querySelector('.hero-art');\n  let desktop=false,travel=0,distance=0,stickyTop=64,frame=0,observer,visualObserver;\n  function setupReveals(){\n    observer?.disconnect();\n    visualObserver?.disconnect();\n    document.documentElement.classList.toggle('motion-ready',!reduced.matches);\n    if(reduced.matches){document.querySelectorAll('.reveal').forEach(el=>el.classList.add('revealed'));document.querySelectorAll('.service-visual,.agent-interactive').forEach(el=>el.classList.add('visual-in-view'));return;}\n    observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target);} }),{threshold:.08,rootMargin:'0px 0px -30px 0px'});\n    document.querySelectorAll('.reveal:not(.revealed)').forEach(el=>observer.observe(el));\n    visualObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{\n      if(entry.isIntersecting)entry.target.classList.add('visual-in-view');\n      entry.target.classList.toggle('animation-paused',!entry.isIntersecting);\n    }),{threshold:.15});\n    document.querySelectorAll('.service-visual,.agent-interactive,.hero-art').forEach(el=>visualObserver.observe(el));\n  }\n  function resize(){\n    effects.resize();\n    const tabs=document.querySelector('.process-tabs');\n    tabs?.setAttribute('aria-orientation',window.innerWidth<=767?'horizontal':'vertical');\n    if(!showcase)return;\n    const previousProgress=getProgress();\n    desktop=window.innerWidth>=1000&&window.innerHeight>=650&&!reduced.matches;\n    showcase.classList.toggle('is-pinned',desktop);\n    if(desktop&&sticky.offsetHeight>window.innerHeight-76){desktop=false;showcase.classList.remove('is-pinned');}\n    track.style.transform='';\n    viewport.scrollLeft=0;\n    const viewportStyle=getComputedStyle(viewport);\n    const totalWidth=track.scrollWidth+parseFloat(viewportStyle.paddingLeft)+parseFloat(viewportStyle.paddingRight);\n    travel=Math.max(0,totalWidth-viewport.clientWidth);\n    if(desktop){stickyTop=parseFloat(getComputedStyle(sticky).top)||64;distance=travel*.8;showcase.style.height=`${sticky.offsetHeight+distance}px`;}else{showcase.style.height='';distance=0;viewport.scrollLeft=previousProgress*travel;}\n    update();\n  }\n  function getProgress(){if(!showcase)return 0;if(desktop)return Math.min(1,Math.max(0,(stickyTop-showcase.getBoundingClientRect().top)/Math.max(distance,1)));return travel?viewport.scrollLeft/travel:0;}\n  function update(){\n    frame=0;header?.classList.toggle('scrolled',window.scrollY>30);\n    if(showcase){const progress=getProgress();if(desktop)track.style.transform=`translate3d(${-travel*progress}px,0,0)`;progressBar.style.transform=`scaleX(${Math.max(.08,progress)})`;const prev=showcase.querySelector('.showcase-prev'),next=showcase.querySelector('.showcase-next');prev.disabled=progress<=.002;next.disabled=progress>=.998;}\n    if(hero&&!reduced.matches){const amount=Math.min(window.scrollY/800,1);hero.style.setProperty('--scroll-depth',`${amount*70}px`);}\n    effects.update();\n  }\n  const schedule=()=>{if(!frame)frame=requestAnimationFrame(update);};\n  function advance(direction){\n    if(desktop){const amount=(track.querySelector('.showcase-card').offsetWidth+24)/travel;const target=Math.min(1,Math.max(0,getProgress()+direction*amount));window.scrollTo({top:window.scrollY+showcase.getBoundingClientRect().top-stickyTop+distance*target,behavior:'smooth'});}\n    else viewport.scrollBy({left:direction*(track.querySelector('.showcase-card').offsetWidth+parseFloat(getComputedStyle(track).gap)),behavior:reduced.matches?'instant':'smooth'});\n  }\n  showcase?.querySelector('.showcase-prev').addEventListener('click',()=>advance(-1),{signal});\n  showcase?.querySelector('.showcase-next').addEventListener('click',()=>advance(1),{signal});\n  viewport?.addEventListener('scroll',schedule,{passive:true,signal});\n  viewport?.addEventListener('keydown',e=>{if(e.target!==viewport)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();advance(e.key==='ArrowRight'?1:-1);}},{signal});\n  track?.addEventListener('focusin',e=>{if(!desktop)return;const card=e.target.closest('.showcase-card');if(!card)return;const left=card.offsetLeft;const current=getProgress()*travel;if(left<current||left+card.offsetWidth>current+viewport.clientWidth){const target=Math.min(travel,Math.max(0,left-60));window.scrollTo({top:window.scrollY+showcase.getBoundingClientRect().top-stickyTop+distance*(target/travel),behavior:'instant'});}},{signal});\n  window.addEventListener('scroll',schedule,{passive:true,signal});\n  window.addEventListener('resize',resize,{passive:true,signal});\n  reduced.addEventListener('change',()=>{setupReveals();resize();},{signal});\n  if(art&&pointer.matches&&!reduced.matches){hero.addEventListener('pointermove',e=>{if(reduced.matches)return;const bounds=hero.getBoundingClientRect();art.style.setProperty('--pointer-x',`${(e.clientX/bounds.width-.5)*15}px`);art.style.setProperty('--pointer-y',`${(e.clientY/bounds.height-.5)*12}px`);},{passive:true,signal});hero.addEventListener('pointerleave',()=>{art.style.setProperty('--pointer-x','0px');art.style.setProperty('--pointer-y','0px');},{signal});}\n  if(pointer.matches)document.querySelectorAll('.service-card').forEach(card=>{card.addEventListener('pointermove',e=>{if(reduced.matches)return;const rect=card.getBoundingClientRect();card.style.setProperty('--light-x',`${e.clientX-rect.left}px`);card.style.setProperty('--light-y',`${e.clientY-rect.top}px`);},{passive:true,signal});});\n  setupReveals();resize();update();\n  document.fonts?.ready.then(()=>{if(!signal.aborted)resize();});\n  return ()=>{abort.abort();observer?.disconnect();visualObserver?.disconnect();effects.destroy();cleanupPixels();cancelAnimationFrame(frame);};\n}\n");
embeddedAssets.set("/src/experience.js", "import { icons, serviceVisual, comparisonVisual } from './visuals.js';\n\nexport const experienceScenes=[\n  {name:'The experience',label:'DIGITAL EXPERIENCE',title:'Same business.<br>A different feeling.',text:'Design shapes the way people see your business. Move the divider to explore how a considered experience changes the first impression.',slug:'digital-presence',number:'01',caption:'Drag to reveal. Feel the difference.'},\n  {name:'The perspective',label:'MARKET INTELLIGENCE',title:'Information,<br>with direction.',text:'Bring scattered signals into one clear perspective. Explore an illustrative interface connecting audience behavior and market opportunity.',slug:'market-intelligence',type:'intelligence',number:'02',caption:'A clearer picture of the opportunity.'},\n  {name:'The connection',label:'AI-ASSISTED WORKFLOW',title:'Separate tasks.<br>Shared intelligence.',text:'Connected workflows give every task a place in the bigger picture. Human direction guides the research, analysis, and optimization.',slug:'agentic-ai-marketing',type:'ai',number:'03',caption:'Purposeful automation. Human direction.'}\n];\n\nexport function experiencePanel(index){\n  const scene=experienceScenes[index];\n  return `<div class=\"experience-stage-header\"><span><i class=\"tiny-dot violet\"></i> ${scene.label}</span><span>EXPLORATION ${scene.number} / 03</span></div><div class=\"experience-canvas ${scene.type?'canvas-dashboard':'canvas-design'}\"><div class=\"experience-grid\"></div><div class=\"experience-frame\">${scene.type?serviceVisual(scene.type,'lab-visual'):comparisonVisual()}</div><span class=\"experience-coordinate coordinate-top\">+ 01.24 / 08.36</span><span class=\"experience-coordinate coordinate-bottom\">+ AV — DESIGN SYSTEM</span></div><div class=\"experience-stage-footer\"><span>${scene.caption}</span><span>CONCEPT DEMONSTRATION ${icons.diagonal}</span></div>`;\n}\n\nexport function experienceSection(){\n  const scene=experienceScenes[0];\n  return `<section id=\"experience\" class=\"experience-section\"><div class=\"container\"><div class=\"section-top\"><span><i>AV / LAB</i> POSSIBILITIES IN MOTION</span><span>EXPLORE. INTERACT. IMAGINE.</span></div><div class=\"experience-heading reveal\"><div class=\"eyebrow\"><span class=\"eyebrow-line\"></span> THE EXPERIENCE IS THE DIFFERENCE</div><h2>Don’t just explain it.<br><span class=\"text-gradient\">Let them experience it.</span></h2></div><div class=\"experience-layout reveal\"><div class=\"experience-sidebar\"><div class=\"experience-tabs\" role=\"tablist\" aria-label=\"Explore our design and technology capabilities\" aria-orientation=\"vertical\">${experienceScenes.map((s,i)=>`<button id=\"experience-tab-${i}\" class=\"experience-tab ${i===0?'selected':''}\" data-scene=\"${i}\" role=\"tab\" aria-selected=\"${i===0}\" aria-controls=\"experience-panel\" tabindex=\"${i===0?'0':'-1'}\"><span>0${i+1}</span><strong>${s.name}</strong>${icons.diagonal}</button>`).join('')}</div><div class=\"experience-copy\" aria-live=\"polite\"><span class=\"experience-scene-label\">${scene.label}</span><h3>${scene.title}</h3><p>${scene.text}</p><a class=\"text-link experience-service-link\" href=\"/services/${scene.slug}\">Explore the capability ${icons.diagonal}</a></div><div class=\"experience-disclosure\">DESIGN EXPLORATIONS<br><span>Concept interfaces. Illustrative data.</span></div></div><div id=\"experience-panel\" class=\"experience-stage\" role=\"tabpanel\" aria-labelledby=\"experience-tab-0\">${experiencePanel(0)}</div></div></div></section>`;\n}\n\nexport function bindExperience(signal){\n  const section=document.querySelector('.experience-section');\n  if(!section)return;\n  const tabs=[...section.querySelectorAll('.experience-tab')];\n  const panel=section.querySelector('#experience-panel');\n  function bindComparison(){\n    const range=panel.querySelector('.comparison-range');\n    range?.addEventListener('input',()=>{range.closest('.design-comparison').style.setProperty('--comparison',`${range.value}%`);range.setAttribute('aria-valuetext',`${range.value} percent considered design visible`);},{signal});\n  }\n  function select(index,focus=false){\n    tabs.forEach((tab,i)=>{tab.classList.toggle('selected',i===index);tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;});\n    const scene=experienceScenes[index];\n    panel.setAttribute('aria-labelledby',`experience-tab-${index}`);panel.innerHTML=experiencePanel(index);panel.dataset.scene=String(index);\n    section.querySelector('.experience-copy').innerHTML=`<span class=\"experience-scene-label\">${scene.label}</span><h3>${scene.title}</h3><p>${scene.text}</p><a class=\"text-link experience-service-link\" href=\"/services/${scene.slug}\">Explore the capability ${icons.diagonal}</a>`;\n    panel.querySelector('.service-visual')?.classList.add('visual-in-view');\n    bindComparison();\n    if(focus)tabs[index].focus();\n  }\n  tabs.forEach((tab,index)=>{\n    tab.addEventListener('click',()=>select(index),{signal});\n    tab.addEventListener('keydown',e=>{let next=index;if(['ArrowDown','ArrowRight'].includes(e.key))next=(index+1)%tabs.length;else if(['ArrowUp','ArrowLeft'].includes(e.key))next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();select(next,true);},{signal});\n  });\n  bindComparison();\n}\n");
embeddedAssets.set("/src/studio.js", "import { services } from './data.js';\nimport { icons, logo, serviceVisual } from './visuals.js';\n\nexport const insights=[\n  {slug:'beyond-the-website',category:'DIGITAL EXPERIENCE',title:'Your website is a beginning. Build the system around it.',description:'A useful digital experience connects your brand, customer journeys, and the decisions that come next.',type:'presence',read:'4 MIN READ',sections:[\n    ['Start with the customer’s next step','A strong website makes the business easy to understand and gives the visitor a useful next action. Before choosing layouts or tools, define who the site serves, what they need to know, and how you can help them move forward.'],\n    ['Connect the experience to your operations','An inquiry should enter a process someone can actually follow. Connect the website to a responsible person, an agreed response workflow, and an appropriate place to keep customer information. A polished form without a delivery process creates a gap between the experience and the business.'],\n    ['Measure useful signals','Choose a small set of measures that reflects the business objective. Relevant inquiries, completed journeys, and useful search traffic can explain more than page views alone. Define what each measure means before collecting it.'],\n    ['Improve with evidence','Use customer questions, observed friction, and performance data to decide what to refine. Your first release is a foundation. A practical review rhythm helps that foundation become more useful over time.']\n  ]},\n  {slug:'research-before-reach',category:'MARKET INTELLIGENCE',title:'Before reaching more people, understand the right people.',description:'Audience research gives design and marketing a clearer direction. Here is where to begin.',type:'intelligence',read:'3 MIN READ',sections:[\n    ['Begin with a real question','Good research is connected to a decision. Are you choosing a market, refining an offer, or improving a customer journey? A clear question keeps the research focused and helps you distinguish useful evidence from interesting background information.'],\n    ['Combine conversations and signals','Customer conversations reveal motivations and objections. Search behavior, existing inquiries, and competitor positioning provide another perspective. Compare sources, acknowledge gaps, and avoid treating a single signal as a complete picture.'],\n    ['Translate findings into choices','Research should help you decide where to focus, what to communicate, and which channels are relevant. Summarize the evidence, document the assumptions, and identify the next question that needs an experiment.'],\n    ['Keep the picture current','Markets and customer needs change. Review important assumptions regularly and use new evidence to adjust the strategy. Research is most useful as an ongoing input to judgment.']\n  ]},\n  {slug:'human-guided-ai',category:'AI & AUTOMATION',title:'Better automation starts with clear human direction.',description:'Define the task, the tools, and the review points before connecting an AI workflow.',type:'ai',read:'4 MIN READ',sections:[\n    ['Define the task before the agent','Start with a process that has a clear input and an understandable output. Research summaries, reporting preparation, and first drafts can be useful places to investigate AI assistance. Establish the expected quality and the person responsible for reviewing it.'],\n    ['Agree on tools and permissions','A workflow should access only the sources and integrations approved for the engagement. Decide what it can read, what it can propose, and which actions require a person’s approval. Permissions are part of the design.'],\n    ['Make handoffs visible','Show where research becomes analysis and where a recommendation awaits review. Clear handoffs help people understand the work and intervene when information is incomplete or an output is unsuitable.'],\n    ['Measure the workflow itself','Review output quality, time spent checking results, and failures or exceptions. A useful workflow saves appropriate effort while preserving accountability. Improve it around observed results, not the promise of autonomy.']\n  ]}\n];\nexport const studioRoutes=['/solutions','/engagements','/insights',...insights.map(x=>`/insights/${x.slug}`)];\n\nconst eyebrow=text=>`<div class=\"eyebrow\"><span class=\"eyebrow-line\"></span>${text}</div>`;\nconst button=(label,href='/contact',secondary=false)=>`<a class=\"button button-${secondary?'outline':'primary'}\" href=\"${href}\"><span>${label}</span>${icons.arrow}</a>`;\n\nexport function platformVisual(){\n  return `<div class=\"platform-window\" aria-label=\"Concept interface connecting your growth strategy, research, and digital experience\"><div class=\"platform-titlebar\"><span class=\"window-dots\"><i></i><i></i><i></i></span><span>AVENTRIXX / GROWTH WORKSPACE</span><span>CONCEPT INTERFACE</span></div><div class=\"platform-body\"><aside class=\"platform-sidebar\"><span class=\"platform-brand\">${logo} aventrixx.</span><span class=\"platform-nav selected\">${icons.target} Overview</span><span class=\"platform-nav\">${icons.chart} Market research</span><span class=\"platform-nav\">${icons.globe} Digital experience</span><span class=\"platform-nav\">${icons.network} Workflows</span><span class=\"platform-sidebar-note\">A CONNECTED PERSPECTIVE</span></aside><div class=\"platform-main\"><div class=\"platform-heading\"><div><small>YOUR BUSINESS / THE BIGGER PICTURE</small><h3>Make the next move<br>with clarity.</h3></div><span class=\"platform-badge\"><i class=\"tiny-dot\"></i> Human guided</span></div><div class=\"platform-pillars\"><div><span>01 / DISCOVER</span><strong>Understand<br>the opportunity.</strong><small>Audience · Market · Intent</small>${icons.search}</div><div><span>02 / CONNECT</span><strong>Build a useful<br>experience.</strong><small>Design · Content · Journey</small>${icons.globe}</div><div><span>03 / GROW</span><strong>Move forward<br>intelligently.</strong><small>Measure · Refine · Repeat</small>${icons.growth}</div></div><div class=\"platform-bottom\"><div class=\"platform-chart\"><span>A CONNECTED DIRECTION</span><svg viewBox=\"0 0 420 110\" fill=\"none\" aria-hidden=\"true\"><path d=\"M0 25h420M0 60h420M0 95h420\" stroke=\"#fff\" stroke-opacity=\".06\"/><path class=\"draw-path\" d=\"M0 100c45 0 45-34 90-34s65 30 95-5 65 0 105-27 65 3 100-23 25-4 30-6\" stroke=\"#32f08c\" stroke-width=\"2\"/><path d=\"M0 100c40-3 60-8 100-12s110-25 160-18 90-35 160-36\" stroke=\"#8b939a\" stroke-width=\"1.5\" stroke-dasharray=\"4 6\"/></svg><small>Illustrative direction. No client results or forecasts.</small></div><div class=\"platform-workflow\"><span>THE NEXT STEPS</span><div>${icons.check} Research brief <small>Define</small></div><div>${icons.check} Experience strategy <small>Connect</small></div><div>${icons.check} Growth roadmap <small>Build</small></div></div></div></div></div></div>`;\n}\n\nexport function referenceHero(){\n  return `<section class=\"signal-hero\"><div class=\"pixel-field\" aria-hidden=\"true\"><canvas class=\"pixel-canvas\"></canvas><div class=\"pixel-static\"></div></div><div class=\"container signal-hero-inner\"><div class=\"signal-hero-top\"><span><i class=\"status-dot\"></i> CREATIVE TECHNOLOGY. INTELLIGENT GROWTH.</span><span>YOUR NEXT CHAPTER / AVENTRIXX</span></div><div class=\"signal-hero-content\"><div class=\"signal-hero-copy\"><h1><span>Your next chapter.</span><br>Starts with <span class=\"hero-brand-text\">Aventrixx.</span></h1><p>Digital experiences, market intelligence, and AI-assisted marketing.<br>A connected system for businesses ready to move forward.</p></div><div class=\"signal-hero-actions\">${button('Build My Growth Strategy')}<a class=\"text-link\" href=\"/#capabilities\">Explore our capabilities ${icons.diagonal}</a></div></div><div class=\"signal-hero-bottom\"><a href=\"/#unlock\">SCROLL TO EXPLORE ↓</a><span>STRATEGY → EXPERIENCE → GROWTH</span></div></div></section>`;\n}\n\nexport function unlockSection(){\n  const choices=[\n    {name:'A connected growth strategy',text:'Bring your website, research, and customer acquisition into one practical direction. Start with your business and build the connections that matter.',type:'platform',link:'business-growth'},\n    {name:'A digital experience with purpose',text:'Express your brand, earn trust, and make the next step feel effortless. Design, content, and development connect around your customer.',type:'presence',link:'digital-presence'},\n    {name:'A clearer view of your market',text:'Understand audience needs, competitive positioning, and the opportunities behind your next move. Research gives the strategy a stronger foundation.',type:'intelligence',link:'market-intelligence'},\n    {name:'AI workflows with human direction',text:'Connect research, analysis, and measurement through approved tools. People define the scope, review the outputs, and decide what happens next.',type:'ai',link:'agentic-ai-marketing'}\n  ];\n  return `<section id=\"unlock\" class=\"unlock-section container\"><div class=\"unlock-heading reveal\">${eyebrow('ONE BUSINESS. CONNECTED POSSIBILITIES.')}<h2>What you’ll unlock<br><span>with Aventrixx.</span></h2></div><div class=\"unlock-layout reveal\"><div class=\"unlock-tabs\" role=\"tablist\" aria-label=\"Explore connected growth possibilities\" aria-orientation=\"vertical\">${choices.map((x,i)=>`<button id=\"unlock-tab-${i}\" class=\"unlock-tab ${i===0?'selected':''}\" role=\"tab\" aria-selected=\"${i===0}\" aria-controls=\"unlock-panel-${i}\" tabindex=\"${i===0?0:-1}\" data-unlock=\"${i}\"><span>[0${i}]</span><strong>${x.name}</strong>${icons.arrow}</button>`).join('')}</div><div class=\"unlock-panels\">${choices.map((x,i)=>`<div id=\"unlock-panel-${i}\" class=\"unlock-panel\" role=\"tabpanel\" aria-labelledby=\"unlock-tab-${i}\" ${i!==0?'hidden':''}><div class=\"unlock-visual\">${x.type==='platform'?platformVisual():serviceVisual(x.type,'unlock-service-visual')}</div><div class=\"unlock-panel-copy\"><p>${x.text}</p><a class=\"text-link\" href=\"/services/${x.link}\">Explore the capability ${icons.diagonal}</a></div></div>`).join('')}</div></div></section>`;\n}\n\nexport function insightsCards(){return insights.map((x,i)=>`<a class=\"insight-card\" href=\"/insights/${x.slug}\"><div class=\"insight-cover cover-${x.type}\"><span>AV / JOURNAL</span><div class=\"insight-glyph\" aria-hidden=\"true\">${icons[['globe','chart','network'][i]]}</div><strong>${['Build the<br>connections.','Clarity<br>comes first.','Human vision.<br>AI assistance.'][i]}</strong><i>0${i+1}</i></div><div class=\"insight-meta\"><span>${x.category}</span><span>${x.read}</span></div><h3>${x.title}</h3><p>${x.description}</p><span class=\"text-link\">Read the insight ${icons.diagonal}</span></a>`).join('');}\nexport function journalSection(){return `<section class=\"journal-section container\"><div class=\"section-heading\"><div>${eyebrow('PERSPECTIVES FROM THE STUDIO')}<h2>Ideas for what’s next.</h2></div><a class=\"text-link\" href=\"/insights\">All insights ${icons.diagonal}</a></div><div class=\"insight-grid\">${insightsCards()}</div></section>`;}\n\nfunction faq(){return `<section class=\"faq-section container\">${eyebrow('BEFORE WE BEGIN')}<h2>A few good questions.</h2><div class=\"faq-list\">${[\n  ['Do I need every capability?','No. We begin with your business objectives and define a focused combination of services around what is useful for your next stage.'],\n  ['How are engagements priced?','Each scope is quoted after discovery. Deliverables, milestones, pricing, review points, and responsibilities are agreed in writing before work starts.'],\n  ['Can you work with our existing website or tools?','We review your current infrastructure first. Where practical, we improve and connect the systems you already use. Proposed integrations are agreed for each engagement.'],\n  ['What does AI-assisted marketing actually mean?','We design workflows for defined tasks such as research, analysis, and reporting, using approved tools and human review. Scope and permissions are established before implementation.'],\n  ['Do you guarantee business results?','No specific ranking, lead volume, or revenue outcome is guaranteed. We agree on useful objectives, measurement, and a review process, then refine around evidence.']\n].map(([q,a])=>`<details><summary>${q}${icons.plus}</summary><p>${a}</p></details>`).join('')}</div></section>`;}\n\nexport function renderStudio(path){\n  if(path==='/solutions')return {title:'Connected Business Solutions',html:`<main id=\"main\"><section class=\"page-hero container studio-centered\">${eyebrow('BUILT AROUND YOUR BUSINESS')}<h1>One connected partner.<br>For your next stage of growth.</h1><p>Bring digital experience, market insight, and purposeful automation together.<br>Aventrixx connects the strategy with the work that makes it real.</p><div class=\"studio-hero-actions\">${button('Build My Growth Strategy')}${button('Explore Capabilities','/services',true)}</div></section><section class=\"container platform-showcase\">${platformVisual()}</section><section class=\"solution-features container\"><div class=\"section-heading\"><h2>From ambition to action.<br><span class=\"muted\">With a clearer direction.</span></h2></div>${[\n    ['01','A business-first strategy','Understand the challenge before choosing the tools. Research connects your objectives with a practical roadmap.','intelligence'],\n    ['02','An experience built for your customers','Connect your brand, content, and customer journey in a digital experience designed around useful next steps.','presence'],\n    ['03','Intelligence with human oversight','Connect defined workflows and approved integrations while keeping people responsible for the strategy and decisions.','ai']\n  ].map(([n,title,text,type])=>`<article class=\"solution-row reveal\"><div><span class=\"solution-number\">[${n}]</span><h3>${title}</h3><p>${text}</p><a class=\"text-link\" href=\"/services/${services.find(s=>s.type===type).slug}\">Explore the capability ${icons.diagonal}</a></div>${serviceVisual(type,'solution-visual')}</article>`).join('')}</section><section class=\"solution-principles container\"><h2>Designed for trust.</h2><div>${['Agreed scope and responsibilities','Approved tools and permissions','Clear measurement and review','Honest expectations'].map(x=>`<p>${icons.check}${x}</p>`).join('')}</div></section>${faq()}</main>`};\n  if(path==='/engagements')return {title:'Ways to Work Together',html:`<main id=\"main\"><section class=\"page-hero container studio-centered\">${eyebrow('A FOCUSED SCOPE. A SHARED DIRECTION.')}<h1>Ways to work together.</h1><p>Start where your business needs you to.<br>Every engagement begins with discovery and a tailored scope.</p></section><section class=\"engagement-grid container\">${[\n    {name:'Discover',label:'FIND YOUR DIRECTION',text:'Clarity before commitment.',items:['Business and digital review','Audience and market research','Opportunity assessment','A prioritized roadmap'],action:'Start with Discovery'},\n    {name:'Build',label:'CREATE THE FOUNDATIONS',text:'Bring the strategy to life.',items:['Brand-aligned digital experience','Responsive development','Customer acquisition journeys','Agreed system integrations'],action:'Discuss Your Project'},\n    {name:'Connect & Grow',label:'REFINE THE SYSTEM',text:'Progress with purpose.',items:['Connected marketing strategy','AI-assisted workflow design','Measurement and reporting','Ongoing review and optimization'],action:'Plan Your Next Stage'}\n  ].map((x,i)=>`<article class=\"engagement-card ${i===1?'featured':''}\"><span class=\"engagement-label\">${x.label}</span><h2>${x.name}</h2><span class=\"engagement-price\">Tailored scope</span><p>${x.text}</p><div>${x.items.map(item=>`<span>${icons.check}${item}</span>`).join('')}</div>${button(x.action)}<small>Quoted after discovery. No automatic subscription.</small></article>`).join('')}</section><p class=\"engagement-note container\">Deliverables, timing, and pricing are agreed in writing for each engagement.</p>${faq()}</main>`};\n  if(path==='/insights')return {title:'Studio Insights',html:`<main id=\"main\"><section class=\"page-hero container studio-centered\">${eyebrow('AVENTRIXX / JOURNAL')}<h1>Ideas for what’s next.</h1><p>Perspectives on digital experience, market intelligence,<br>and a more considered way to grow.</p></section><section class=\"insights-index container\"><div class=\"insight-grid\">${insightsCards()}</div></section></main>`};\n  const article=insights.find(x=>path===`/insights/${x.slug}`);\n  if(article)return {title:article.title,html:`<main id=\"main\"><section class=\"page-hero container article-hero\"><a class=\"breadcrumb\" href=\"/insights\">← ALL INSIGHTS</a>${eyebrow(article.category)}<h1>${article.title}</h1><p>${article.description}</p><div class=\"article-meta\"><span>AVENTRIXX STUDIO</span><span>${article.read}</span></div></section><div class=\"article-layout container\"><nav class=\"article-toc\" aria-label=\"On this page\"><span>ON THIS PAGE</span>${article.sections.map(([title],i)=>`<a href=\"/insights/${article.slug}#article-section-${i}\">${title}</a>`).join('')}</nav><article class=\"article-copy\">${article.sections.map(([title,text],i)=>`<section id=\"article-section-${i}\"><h2>${title}</h2><p>${text}</p></section>`).join('')}<div class=\"article-next\"><a class=\"text-link\" href=\"/insights\">All insights ${icons.arrow}</a>${button('Discuss Your Next Chapter')}</div></article></div></main>`};\n  return null;\n}\n\nexport function bindStudio(signal){\n  const tabs=[...document.querySelectorAll('.unlock-tab')];\n  const select=(index,focus=false)=>{tabs.forEach((tab,i)=>{tab.classList.toggle('selected',i===index);tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;document.querySelector(`#unlock-panel-${i}`).hidden=i!==index;});document.querySelector(`#unlock-panel-${index} .service-visual`)?.classList.add('visual-in-view');if(focus)tabs[index].focus();};\n  tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(i),{signal});tab.addEventListener('keydown',event=>{let next=i;if(['ArrowDown','ArrowRight'].includes(event.key))next=(i+1)%tabs.length;else if(['ArrowUp','ArrowLeft'].includes(event.key))next=(i+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();select(next,true);},{signal});});\n}\n");
embeddedAssets.set("/src/pixels.js", "export function initPixelField({signal}){\n  const canvas=document.querySelector('.pixel-canvas');\n  if(!canvas)return ()=>{};\n  const ctx=canvas.getContext('2d',{alpha:false});\n  if(!ctx)return ()=>{};\n  const field=canvas.closest('.pixel-field');\n  const hero=field.closest('.signal-hero');\n  const reduced=matchMedia('(prefers-reduced-motion: reduce)');\n  const pointer=matchMedia('(hover: hover) and (pointer: fine)');\n  let width=0,height=0,frame=0,visible=false,last=0,time=0,px=.5,py=.5,targetX=.5,targetY=.5;\n  let spacing=7,pixelSize=4,frameInterval=1000/30;\n  const points=[];\n\n  // A small, repeatable noise map keeps the field coherent between frames.\n  const noiseMap=new Float32Array(128*128);\n  let seed=48271;\n  for(let i=0;i<noiseMap.length;i++){seed=(seed*16807)%2147483647;noiseMap[i]=seed/2147483647;}\n  function noise(x,y){\n    const ix=Math.floor(x),iy=Math.floor(y);\n    let fx=x-ix,fy=y-iy;fx=fx*fx*(3-2*fx);fy=fy*fy*(3-2*fy);\n    const x0=ix&127,x1=(ix+1)&127,y0=(iy&127)*128,y1=((iy+1)&127)*128;\n    const a=noiseMap[y0+x0],b=noiseMap[y0+x1],c=noiseMap[y1+x0],d=noiseMap[y1+x1];\n    return a+(b-a)*fx+(c-a+(a-b-c+d)*fx)*fy;\n  }\n  const shades=Array.from({length:32},(_,i)=>`rgba(174,184,179,${i/31*.67})`);\n  const greenShades=Array.from({length:32},(_,i)=>`rgba(30,181,117,${i/31*.48})`);\n  const clamp=value=>Math.max(0,Math.min(1,value));\n\n  function resize(){\n    const rect=field.getBoundingClientRect();width=rect.width;height=rect.height;\n    if(!width||!height)return;\n    const ratio=Math.min(devicePixelRatio||1,1.5);\n    canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);\n    ctx.setTransform(ratio,0,0,ratio,0,0);\n    // Keep the grid crisp and bound the work on large monitors.\n    spacing=Math.max(width<768?6:7,Math.ceil(Math.sqrt(width*height/36000)));\n    pixelSize=Math.max(3,spacing-3);frameInterval=1000/(width<768?24:30);\n    points.length=0;\n    const scale=1/Math.min(width,1100);\n    for(let y=0;y<height;y+=spacing)for(let x=0;x<width;x+=spacing){\n      const random=noiseMap[((Math.floor(y/spacing)*37)&127)*128+((Math.floor(x/spacing)*53)&127)];\n      points.push({x,y,u:x*scale,v:y*scale,random,nx:x/width,ny:y/height});\n    }\n    draw();\n  }\n  function draw(){\n    ctx.fillStyle='#0a0b0d';ctx.fillRect(0,0,width,height);\n    const phase=reduced.matches?0:time;\n    const driftX=phase*.19,driftY=phase*.095;\n    const hasPointer=pointer.matches&&!reduced.matches;\n    px+=(targetX-px)*.08;py+=(targetY-py)*.08;\n    for(const point of points){\n      // Evolving density makes islands gather, flow, and dissolve even\n      // when the pointer is still, rather than shifting a fixed dot pattern.\n      const warp=noise(point.u*2.1+driftY+17,point.v*2.1-driftX*.6+9)-.5;\n      const broad=noise(point.u*3.1+driftX+warp*.85+4,point.v*3.1-driftY+warp*.55+12);\n      const detail=noise(point.u*7.8-driftX*.65+28,point.v*7.8+driftY*.7+36);\n      const density=broad*.78+detail*.22;\n      const core=clamp((density-.39)*4.4);\n      const edge=clamp((core-point.random*.48)*3.2);\n      if(edge<=0)continue;\n      const dx=point.nx-px,dy=point.ny-py;\n      const light=hasPointer?Math.max(0,1-(dx*dx+dy*dy)*16)*.1:0;\n      const intensity=clamp(edge*(.3+point.random*.54)+light);\n      const shade=Math.round(intensity*31);\n      if(!shade)continue;\n      ctx.fillStyle=point.random>.63&&core>.36?greenShades[shade]:shades[shade];\n      ctx.fillRect(point.x,point.y,pixelSize,pixelSize);\n    }\n    field.classList.add('pixels-ready');\n  }\n  function animate(now){\n    if(!visible||document.hidden||reduced.matches){frame=0;return;}\n    const elapsed=now-last;\n    if(elapsed>=frameInterval){\n      const remainder=elapsed%frameInterval;\n      time+=Math.min((elapsed-remainder)/1000,.1);last=now-remainder;draw();\n    }\n    frame=requestAnimationFrame(animate);\n  }\n  const stop=()=>{cancelAnimationFrame(frame);frame=0;};\n  const start=()=>{if(visible&&!document.hidden&&!reduced.matches&&!frame){last=performance.now();frame=requestAnimationFrame(animate);}};\n  const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)start();else stop();},{threshold:.01});\n  observer.observe(field);\n  const resizeObserver=new ResizeObserver(resize);resizeObserver.observe(field);\n  hero.addEventListener('pointermove',event=>{\n    if(!pointer.matches||reduced.matches)return;\n    const rect=field.getBoundingClientRect();\n    targetX=clamp((event.clientX-rect.left)/width);targetY=clamp((event.clientY-rect.top)/height);\n  },{passive:true,signal});\n  hero.addEventListener('pointerleave',()=>{targetX=.5;targetY=.5;},{signal});\n  reduced.addEventListener('change',()=>{stop();draw();start();},{signal});\n  document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else start();},{signal});\n  resize();\n  return ()=>{stop();observer.disconnect();resizeObserver.disconnect();};\n}\n");
embeddedAssets.set("/src/effects.js", "export function initEffects({signal,reduced,pointer}){\n  const band=document.querySelector('.kinetic-band');\n  const bandTrack=band?.querySelector('.kinetic-track');\n  const reading=document.querySelector('.reading-progress i');\n  const showcase=document.querySelector('.showcase-section');\n  const cards=[...document.querySelectorAll('.showcase-card')];\n  const sceneTabs=document.querySelector('.experience-tabs');\n  const effectPanels=[...document.querySelectorAll('.project-visual,.experience-stage')];\n  let observer;\n  function resize(){sceneTabs?.setAttribute('aria-orientation',innerWidth<=767?'horizontal':'vertical');}\n  function update(){\n    const total=document.documentElement.scrollHeight-innerHeight;\n    if(reading)reading.style.transform=`scaleX(${total>0?Math.min(1,scrollY/total):0})`;\n    if(reduced.matches){if(bandTrack)bandTrack.style.transform='';cards.forEach(card=>{card.style.removeProperty('--card-angle');card.style.removeProperty('--card-depth');card.style.removeProperty('--card-light');});return;}\n    if(bandTrack){const rect=band.getBoundingClientRect();if(rect.top<innerHeight&&rect.bottom>0)bandTrack.style.transform=`translate3d(${-(innerHeight-rect.top)*.24}px,0,0)`;}\n    if(showcase?.classList.contains('is-pinned')){\n      const rect=showcase.getBoundingClientRect();\n      if(rect.top<innerHeight&&rect.bottom>0){\n        const focusX=innerWidth*.4;\n        let closest=Infinity,selected=0;\n        cards.forEach((card,i)=>{\n          const bounds=card.getBoundingClientRect();\n          const offset=(bounds.left+bounds.width/2-focusX)/innerWidth;\n          const amount=Math.min(1,Math.abs(offset)*1.5);\n          card.style.setProperty('--card-angle',`${Math.max(-8,Math.min(8,offset*-14))}deg`);\n          card.style.setProperty('--card-depth',`${amount*12}px`);\n          card.style.setProperty('--card-light',`${1-amount*.28}`);\n          if(Math.abs(offset)<closest){closest=Math.abs(offset);selected=i;}\n        });\n        showcase.dataset.activeCapability=String(selected);\n        cards.forEach((card,i)=>card.classList.toggle('is-featured',i===selected));\n      }\n    }\n  }\n  function pointerPanel(panel){\n    panel.addEventListener('pointermove',event=>{\n      if(!pointer.matches||reduced.matches)return;\n      const rect=panel.getBoundingClientRect();\n      const x=(event.clientX-rect.left)/rect.width,y=(event.clientY-rect.top)/rect.height;\n      panel.style.setProperty('--tilt-x',`${(y-.5)*-4}deg`);panel.style.setProperty('--tilt-y',`${(x-.5)*5}deg`);\n      panel.style.setProperty('--spotlight-x',`${x*100}%`);panel.style.setProperty('--spotlight-y',`${y*100}%`);\n    },{passive:true,signal});\n    panel.addEventListener('pointerleave',()=>{panel.style.setProperty('--tilt-x','0deg');panel.style.setProperty('--tilt-y','0deg');},{signal});\n  }\n  effectPanels.forEach(pointerPanel);\n  document.querySelectorAll('.button-primary').forEach(button=>{\n    button.addEventListener('pointermove',event=>{\n      if(!pointer.matches||reduced.matches||button.disabled)return;\n      const rect=button.getBoundingClientRect();\n      button.style.setProperty('--magnet-x',`${((event.clientX-rect.left)/rect.width-.5)*8}px`);\n      button.style.setProperty('--magnet-y',`${((event.clientY-rect.top)/rect.height-.5)*6}px`);\n    },{passive:true,signal});\n    button.addEventListener('pointerleave',()=>{button.style.setProperty('--magnet-x','0px');button.style.setProperty('--magnet-y','0px');},{signal});\n  });\n  observer=new IntersectionObserver(entries=>entries.forEach(entry=>{entry.target.classList.toggle('effects-visible',entry.isIntersecting);}),{threshold:.05});\n  document.querySelectorAll('.hero-art,.experience-stage,.cta-section').forEach(el=>observer.observe(el));\n  const reset=()=>{if(reduced.matches||!pointer.matches){effectPanels.forEach(panel=>{panel.style.setProperty('--tilt-x','0deg');panel.style.setProperty('--tilt-y','0deg');});document.querySelectorAll('.button-primary').forEach(button=>{button.style.setProperty('--magnet-x','0px');button.style.setProperty('--magnet-y','0px');});}resize();update();};\n  reduced.addEventListener('change',reset,{signal});\n  pointer.addEventListener('change',reset,{signal});\n  resize();update();\n  return {update,resize,destroy:()=>observer?.disconnect()};\n}\n");
embeddedAssets.set("/src/validate.js", "import { services } from './data.js';\n\nexport const interests = new Set(['Growth strategy', 'Not sure yet', ...services.map((s) => s.name)]);\n\nexport function validateInquiry(data) {\n  if (!data || typeof data !== 'object' || Array.isArray(data)) return { error: 'Please provide a valid inquiry.' };\n  if (data.website_check) return { error: 'The submission could not be accepted.' };\n  const name = typeof data.name === 'string' ? data.name.trim() : '';\n  const email = typeof data.email === 'string' ? data.email.trim() : '';\n  const company = typeof data.company === 'string' ? data.company.trim() : '';\n  const message = typeof data.message === 'string' ? data.message.trim() : '';\n  const service = typeof data.service === 'string' ? data.service.trim() : '';\n  if (name.length < 2 || name.length > 100) return { error: 'Please enter a name between 2 and 100 characters.' };\n  if (email.length > 254 || !/^\\S+@[^\\s@]+\\.[^\\s@]+$/.test(email)) return { error: 'Please enter a valid email address.' };\n  if (company.length > 200) return { error: 'Please keep your company details under 200 characters.' };\n  if (message.length < 20 || message.length > 5000) return { error: 'Please tell us about your business in 20 to 5,000 characters.' };\n  if (!interests.has(service)) return { error: 'Please select an available service.' };\n  if (data.consent !== true && data.consent !== 'true' && data.consent !== 'on') return { error: 'Please agree to the privacy policy before submitting.' };\n  return { value: { name, email, company, service, message, consent: true } };\n}\n");
